// Get previous month date range
const now = new Date();
const firstDayLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const lastDayLastMonth = new Date(now.getFullYear(), now.getMonth(), 0);

const monthName = firstDayLastMonth.toLocaleString('en-US', { month: 'long', year: 'numeric' });
const monthShort = firstDayLastMonth.toLocaleString('en-US', { month: 'short', year: 'numeric' });

return [{
  json: {
    monthName,
    monthShort,
    startDate: firstDayLastMonth.toISOString().split('T')[0],
    endDate: lastDayLastMonth.toISOString().split('T')[0],
    year: firstDayLastMonth.getFullYear(),
    month: firstDayLastMonth.getMonth() + 1
  }
}];

// Merge and calculate all financial metrics
const monthData = $('Code - Get Month Range').first().json;
const incomeItems = $('Sheets - Get Incomes').all() || [];
const expenseItems = $('Sheets - Get Expenses').all() || [];

const startDate = new Date(monthData.startDate);
const endDate = new Date(monthData.endDate);

// Filter incomes to the month range
const monthIncomes = incomeItems.filter(item => {
  const date = new Date(item.json.Date);
  return date >= startDate && date <= endDate;
}).map(i => i.json);

// Filter expenses to the month range
const monthExpenses = expenseItems.filter(item => {
  const date = new Date(item.json.Date);
  return date >= startDate && date <= endDate;
}).map(e => e.json);

// Calculate revenue (Customer Payments only)
const customerPayments = monthIncomes.filter(i => i.Type === 'Customer Payment');
const totalRevenue = customerPayments.reduce((sum, i) => sum + (parseFloat(i['Gross Amount']) || 0), 0);

// Calculate Stripe fees
const stripeFees = monthIncomes.filter(i => i.Type === 'Stripe Fee');
const totalStripeFees = Math.abs(stripeFees.reduce((sum, f) => sum + (parseFloat(f['Gross Amount']) || 0), 0));

// Calculate expenses by category
const expensesByCategory = {};
let totalExpenses = 0;

monthExpenses.forEach(expense => {
  const amount = parseFloat(expense.Amount) || 0;
  totalExpenses += amount;

  const category = expense.Category || 'Uncategorized';
  const merchant = expense.Merchant || 'Unknown';
  const date = expense.Date || '';
  const receiptStatus = expense['Receipt Status'] || 'Missing';

  if (!expensesByCategory[category]) {
    expensesByCategory[category] = {
      total: 0,
      count: 0,
      items: []
    };
  }

  expensesByCategory[category].total += amount;
  expensesByCategory[category].count++;
  expensesByCategory[category].items.push({ merchant, amount, date, receiptStatus });
});

// Sort categories by total
const sortedCategories = Object.entries(expensesByCategory)
  .sort((a, b) => b[1].total - a[1].total)
  .map(([name, data]) => ({
    name,
    ...data,
    percentage: totalExpenses > 0 ? (data.total / totalExpenses * 100).toFixed(1) : 0
  }));

// Net profit
const netProfit = totalRevenue - totalExpenses - totalStripeFees;
const profitMargin = totalRevenue > 0 ? (netProfit / totalRevenue * 100).toFixed(1) : 0;

// Missing receipts
const missingReceipts = monthExpenses.filter(exp => exp['Receipt Status'] === 'Missing');
const missingReceiptsTotal = missingReceipts.reduce((sum, exp) => sum + (parseFloat(exp.Amount) || 0), 0);

// Top customers (from revenue)
const customerRevenue = {};
customerPayments.forEach(income => {
  const customer = income.Customer || 'Unknown';
  const amount = parseFloat(income['Gross Amount']) || 0;
  customerRevenue[customer] = (customerRevenue[customer] || 0) + amount;
});

const topCustomers = Object.entries(customerRevenue)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, amount]) => ({ name, amount }));

return [{
  json: {
    ...monthData,
    metrics: {
      totalRevenue,
      totalStripeFees,
      totalExpenses,
      netProfit,
      profitMargin,
      revenueCount: customerPayments.length,
      expenseCount: monthExpenses.length
    },
    sortedCategories,
    topCustomers,
    missingReceipts: {
      count: missingReceipts.length,
      total: missingReceiptsTotal,
      items: missingReceipts.map(exp => ({
        merchant: exp.Merchant || 'Unknown',
        amount: parseFloat(exp.Amount) || 0,
        rowNumber: exp.row_number
      }))
    }
  }
}];

// Format Slack summary
const data = $input.first().json;
const { metrics, sortedCategories, missingReceipts, monthName } = data;
const sheetsUrl = `https://docs.google.com/spreadsheets/d/${$env.GOOGLE_SHEETS_FINANCE_ID}`;

let message = `:bar_chart: *${monthName} Finance Report*\n\n`;
message += `*Revenue:* $${metrics.totalRevenue.toFixed(2)}\n`;
message += `*Expenses:* $${metrics.totalExpenses.toFixed(2)}\n`;
message += `*Net Profit:* *$${metrics.netProfit.toFixed(2)}* (${metrics.profitMargin}% margin)\n\n`;

message += `*Top Categories:*\n`;
sortedCategories.slice(0, 3).forEach((cat, i) => {
  message += `${i + 1}. ${cat.name}: $${cat.total.toFixed(2)} (${cat.percentage}%)\n`;
});
message += `\n`;

message += `:warning: *Action Items:*\n`;
message += `• ${missingReceipts.count} receipts missing ($${missingReceipts.total.toFixed(2)})\n\n`;

message += `<${sheetsUrl}|View Full Report>`;

return [{ json: { ...data, slackMessage: message } }];
